{
  "format": "complete-a-commitment/1",
  "module": {
    "id": "street-team-operating-review",
    "version": "1.1.0",
    "title": "Review a street-team deployment",
    "question": "Which promotion plans meet the recorded staffing, timing, access and spending requirements?",
    "description": "Compare the listed promotion plans for one venue and event. Show every plan that meets the recorded requirements and let the responsible manager record a choice. Guest targets explain the costs to recover; they do not establish promotion effectiveness.",
    "template": {
      "id": "complete-a-commitment",
      "version": 1
    },
    "units": {
      "time": "minute",
      "timeOrigin": "00:00 on the recorded operating date; one same-day local clock",
      "money": "USD cent",
      "count": "qualified staff member"
    },
    "assumptions": [
      "The starter case contains fictional names, records, event details, quantities and financial amounts. Replace and review these values for the planned activity.",
      "Choose one listed promotion plan before departure. The plans are alternatives; this review does not combine teams, stagger shifts or generate responses to later events.",
      "Every staff member counted can cover the required inside work and remains available throughout the full team absence. Individual stations, breaks, travel staffing and other bookings are outside this review.",
      "Available qualified staff equals the roster count minus unavailable staff. Required inside staffing applies throughout the full absence, not only when the team leaves.",
      "Each plan quote includes its full additional cash expense. Past and already committed costs are excluded. Separate discount loss on existing customers reduces contribution but is not another cash charge for sending the team.",
      "Access and spending records are treated as the complete permission register for this review. Missing, false, expired, unrelated or unsourced records do not establish permission. The manager\u2019s choice and approval of the chosen plan are recorded separately.",
      "All times are local minutes from midnight on one operating date. Event exit and customer travel times are planning inputs; they do not establish attendance or acceptance of an offer.",
      "This review does not forecast additional guests, estimate response probabilities or rank expected profit. Not sending a team remains an available option; its zero expense does not make it the preferred choice."
    ],
    "inputs": {
      "parameters": {
        "venueId": {
          "type": "string"
        },
        "eventId": {
          "type": "string"
        },
        "operatingDate": {
          "type": "string"
        },
        "actorId": {
          "type": "string"
        },
        "qualifiedStaff": {
          "type": "integer",
          "unit": "count",
          "minimum": 0
        },
        "unavailableStaff": {
          "type": "integer",
          "unit": "count",
          "minimum": 0
        },
        "minimumInside": {
          "type": "integer",
          "unit": "count",
          "minimum": 0
        },
        "reviewMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "dispatchMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "promotionStartMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "eventExitMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "contactEndMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "staffReturnMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "customerJourneyMinutes": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "latestArrivalMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "expenseLimitMinor": {
          "type": "integer",
          "unit": "money",
          "minimum": 0
        }
      },
      "tables": {
        "options": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "label": {
              "type": "string"
            },
            "promoters": {
              "type": "integer",
              "unit": "count",
              "minimum": 0
            },
            "expenseMinor": {
              "type": "integer",
              "unit": "money",
              "minimum": 0
            }
          }
        },
        "scenarios": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            }
          }
        },
        "access": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "venueId": {
              "type": "string"
            },
            "eventId": {
              "type": "string"
            },
            "operatingDate": {
              "type": "string"
            },
            "activity": {
              "type": "string"
            },
            "granted": {
              "type": "boolean"
            },
            "validFromMinute": {
              "type": "integer",
              "unit": "time",
              "minimum": 0,
              "maximum": 1439
            },
            "validThroughMinute": {
              "type": "integer",
              "unit": "time",
              "minimum": 0,
              "maximum": 1439
            },
            "source": {
              "type": "string"
            }
          }
        },
        "spending": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "venueId": {
              "type": "string"
            },
            "operatingDate": {
              "type": "string"
            },
            "actorId": {
              "type": "string"
            },
            "ceilingMinor": {
              "type": "integer",
              "unit": "money",
              "minimum": 0
            },
            "validFromMinute": {
              "type": "integer",
              "unit": "time",
              "minimum": 0,
              "maximum": 1439
            },
            "validThroughMinute": {
              "type": "integer",
              "unit": "time",
              "minimum": 0,
              "maximum": 1439
            },
            "source": {
              "type": "string"
            }
          }
        },
        "resources": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "capacity": {
              "type": "integer",
              "unit": "count",
              "minimum": 0
            }
          }
        },
        "bookings": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "resource": {
              "type": "string"
            },
            "start": {
              "type": "integer",
              "unit": "time",
              "minimum": 0,
              "maximum": 1439
            },
            "end": {
              "type": "integer",
              "unit": "time",
              "minimum": 0,
              "maximum": 1439
            },
            "amount": {
              "type": "integer",
              "unit": "count",
              "minimum": 0
            }
          }
        }
      }
    },
    "choices": [
      {
        "id": "deployment",
        "domain": {
          "values": [
            "hold",
            "small-standard",
            "large-standard",
            "large-discount"
          ]
        }
      }
    ],
    "scenarioDomain": {
      "table": "scenarios"
    },
    "lookupCoverage": [
      {
        "table": "options",
        "keys": {
          "id": {
            "domain": {
              "values": [
                "hold",
                "small-standard",
                "large-standard",
                "large-discount"
              ]
            }
          }
        }
      }
    ],
    "derived": [
      {
        "id": "promoters",
        "type": "integer",
        "unit": "count",
        "expr": {
          "op": "lookup",
          "table": "options",
          "where": {
            "id": {
              "ref": "choice.deployment"
            }
          },
          "column": "promoters"
        }
      },
      {
        "id": "insideStaff",
        "type": "integer",
        "unit": "count",
        "expr": {
          "op": "sub",
          "args": [
            {
              "op": "sub",
              "args": [
                {
                  "ref": "parameter.qualifiedStaff"
                },
                {
                  "ref": "parameter.unavailableStaff"
                }
              ]
            },
            {
              "ref": "derived.promoters"
            }
          ]
        }
      },
      {
        "id": "customerArrivalMinute",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "add",
          "args": [
            {
              "ref": "parameter.eventExitMinute"
            },
            {
              "ref": "parameter.customerJourneyMinutes"
            }
          ]
        }
      }
    ],
    "activities": [],
    "resources": {
      "definitions": {
        "table": "resources",
        "idColumn": "id",
        "capacityColumn": "capacity"
      },
      "bookings": {
        "table": "bookings",
        "resourceColumn": "resource",
        "startColumn": "start",
        "endColumn": "end",
        "amountColumn": "amount"
      }
    },
    "requirements": [
      {
        "id": "SUFFICIENCY",
        "label": "Inside staffing",
        "meaning": "Retain enough qualified staff for the complete absence.",
        "waivable": false
      },
      {
        "id": "COVERAGE",
        "label": "Promotion plan",
        "meaning": "Use a listed promotion plan with its stated staffing and offer.",
        "waivable": false
      },
      {
        "id": "ACCESS",
        "label": "Access and spending permission",
        "meaning": "Require current recorded permissions for this activity.",
        "waivable": false
      },
      {
        "id": "TIME",
        "label": "Contact and customer arrival",
        "meaning": "Allow time for review, team departure, contact, return and customer travel within the useful arrival window.",
        "waivable": false
      },
      {
        "id": "COST",
        "label": "Additional spending limit",
        "meaning": "Keep the plan\u2019s full additional expense within the recorded limit.",
        "waivable": false
      }
    ],
    "constraints": [
      {
        "id": "published-option-structure",
        "requirement": "COVERAGE",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "and",
              "args": [
                {
                  "op": "eq",
                  "args": [
                    {
                      "ref": "choice.deployment"
                    },
                    {
                      "literal": "hold"
                    }
                  ]
                },
                {
                  "op": "eq",
                  "args": [
                    {
                      "op": "lookup",
                      "table": "options",
                      "where": {
                        "id": {
                          "ref": "choice.deployment"
                        }
                      },
                      "column": "promoters"
                    },
                    {
                      "literal": 0
                    }
                  ]
                },
                {
                  "op": "eq",
                  "args": [
                    {
                      "op": "lookup",
                      "table": "options",
                      "where": {
                        "id": {
                          "ref": "choice.deployment"
                        }
                      },
                      "column": "expenseMinor"
                    },
                    {
                      "literal": 0
                    }
                  ]
                }
              ]
            },
            {
              "op": "and",
              "args": [
                {
                  "op": "eq",
                  "args": [
                    {
                      "ref": "choice.deployment"
                    },
                    {
                      "literal": "small-standard"
                    }
                  ]
                },
                {
                  "op": "eq",
                  "args": [
                    {
                      "op": "lookup",
                      "table": "options",
                      "where": {
                        "id": {
                          "ref": "choice.deployment"
                        }
                      },
                      "column": "promoters"
                    },
                    {
                      "literal": 1
                    }
                  ]
                }
              ]
            },
            {
              "op": "and",
              "args": [
                {
                  "op": "eq",
                  "args": [
                    {
                      "ref": "choice.deployment"
                    },
                    {
                      "literal": "large-standard"
                    }
                  ]
                },
                {
                  "op": "eq",
                  "args": [
                    {
                      "op": "lookup",
                      "table": "options",
                      "where": {
                        "id": {
                          "ref": "choice.deployment"
                        }
                      },
                      "column": "promoters"
                    },
                    {
                      "literal": 2
                    }
                  ]
                }
              ]
            },
            {
              "op": "and",
              "args": [
                {
                  "op": "eq",
                  "args": [
                    {
                      "ref": "choice.deployment"
                    },
                    {
                      "literal": "large-discount"
                    }
                  ]
                },
                {
                  "op": "eq",
                  "args": [
                    {
                      "op": "lookup",
                      "table": "options",
                      "where": {
                        "id": {
                          "ref": "choice.deployment"
                        }
                      },
                      "column": "promoters"
                    },
                    {
                      "literal": 2
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
      {
        "id": "staffing-coverage",
        "requirement": "SUFFICIENCY",
        "kind": "predicate",
        "predicate": {
          "op": "gte",
          "args": [
            {
              "ref": "derived.insideStaff"
            },
            {
              "ref": "parameter.minimumInside"
            }
          ]
        }
      },
      {
        "id": "staffing-register",
        "requirement": "SUFFICIENCY",
        "kind": "predicate",
        "predicate": {
          "op": "lte",
          "args": [
            {
              "ref": "parameter.unavailableStaff"
            },
            {
              "ref": "parameter.qualifiedStaff"
            }
          ]
        }
      },
      {
        "id": "event-access",
        "requirement": "ACCESS",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "choice.deployment"
                },
                {
                  "literal": "hold"
                }
              ]
            },
            {
              "op": "exists",
              "table": "access",
              "where": {
                "venueId": {
                  "ref": "parameter.venueId"
                },
                "eventId": {
                  "ref": "parameter.eventId"
                },
                "operatingDate": {
                  "ref": "parameter.operatingDate"
                },
                "activity": {
                  "literal": "street-promotion"
                }
              },
              "test": {
                "op": "and",
                "args": [
                  {
                    "ref": "row.granted"
                  },
                  {
                    "op": "ne",
                    "args": [
                      {
                        "ref": "row.source"
                      },
                      {
                        "literal": ""
                      }
                    ]
                  },
                  {
                    "op": "lte",
                    "args": [
                      {
                        "ref": "row.validFromMinute"
                      },
                      {
                        "ref": "parameter.promotionStartMinute"
                      }
                    ]
                  },
                  {
                    "op": "gte",
                    "args": [
                      {
                        "ref": "row.validThroughMinute"
                      },
                      {
                        "ref": "parameter.contactEndMinute"
                      }
                    ]
                  }
                ]
              }
            }
          ]
        }
      },
      {
        "id": "spending-permission",
        "requirement": "ACCESS",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "choice.deployment"
                },
                {
                  "literal": "hold"
                }
              ]
            },
            {
              "op": "exists",
              "table": "spending",
              "where": {
                "venueId": {
                  "ref": "parameter.venueId"
                },
                "operatingDate": {
                  "ref": "parameter.operatingDate"
                },
                "actorId": {
                  "ref": "parameter.actorId"
                }
              },
              "test": {
                "op": "and",
                "args": [
                  {
                    "op": "ne",
                    "args": [
                      {
                        "ref": "row.source"
                      },
                      {
                        "literal": ""
                      }
                    ]
                  },
                  {
                    "op": "gte",
                    "args": [
                      {
                        "ref": "row.ceilingMinor"
                      },
                      {
                        "ref": "finance.expense"
                      }
                    ]
                  },
                  {
                    "op": "lte",
                    "args": [
                      {
                        "ref": "row.validFromMinute"
                      },
                      {
                        "ref": "parameter.dispatchMinute"
                      }
                    ]
                  },
                  {
                    "op": "gte",
                    "args": [
                      {
                        "ref": "row.validThroughMinute"
                      },
                      {
                        "ref": "parameter.staffReturnMinute"
                      }
                    ]
                  }
                ]
              }
            }
          ]
        }
      },
      {
        "id": "dispatch-timing",
        "requirement": "TIME",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "choice.deployment"
                },
                {
                  "literal": "hold"
                }
              ]
            },
            {
              "op": "and",
              "args": [
                {
                  "op": "gte",
                  "args": [
                    {
                      "ref": "parameter.dispatchMinute"
                    },
                    {
                      "ref": "parameter.reviewMinute"
                    }
                  ]
                },
                {
                  "op": "lte",
                  "args": [
                    {
                      "ref": "parameter.dispatchMinute"
                    },
                    {
                      "ref": "parameter.promotionStartMinute"
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
      {
        "id": "contact-window",
        "requirement": "TIME",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "choice.deployment"
                },
                {
                  "literal": "hold"
                }
              ]
            },
            {
              "op": "and",
              "args": [
                {
                  "op": "lte",
                  "args": [
                    {
                      "ref": "parameter.promotionStartMinute"
                    },
                    {
                      "ref": "parameter.eventExitMinute"
                    }
                  ]
                },
                {
                  "op": "lte",
                  "args": [
                    {
                      "ref": "parameter.eventExitMinute"
                    },
                    {
                      "ref": "parameter.contactEndMinute"
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
      {
        "id": "useful-arrival",
        "requirement": "TIME",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "choice.deployment"
                },
                {
                  "literal": "hold"
                }
              ]
            },
            {
              "op": "lte",
              "args": [
                {
                  "ref": "derived.customerArrivalMinute"
                },
                {
                  "ref": "parameter.latestArrivalMinute"
                }
              ]
            }
          ]
        }
      },
      {
        "id": "staff-return",
        "requirement": "TIME",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "choice.deployment"
                },
                {
                  "literal": "hold"
                }
              ]
            },
            {
              "op": "gte",
              "args": [
                {
                  "ref": "parameter.staffReturnMinute"
                },
                {
                  "ref": "parameter.contactEndMinute"
                }
              ]
            }
          ]
        }
      },
      {
        "id": "expense-limit",
        "requirement": "COST",
        "kind": "predicate",
        "predicate": {
          "op": "lte",
          "args": [
            {
              "ref": "finance.expense"
            },
            {
              "ref": "parameter.expenseLimitMinor"
            }
          ]
        }
      }
    ],
    "finance": {
      "mode": "expense",
      "charges": [
        {
          "id": "complete-deployment-charge",
          "amount": {
            "op": "lookup",
            "table": "options",
            "where": {
              "id": {
                "ref": "choice.deployment"
              }
            },
            "column": "expenseMinor"
          }
        }
      ],
      "holds": []
    },
    "preference": {
      "mode": "feasibility-only"
    },
    "labels": {
      "plan": "Promotion plan",
      "expense": "Additional promotion expense",
      "choice.deployment": "Promotion plan",
      "derived.promoters": "Promotion team members",
      "derived.insideStaff": "Qualified staff remaining inside",
      "derived.customerArrivalMinute": "Planned guest arrival time",
      "constraint.published-option-structure": "Use one of the four listed promotion plans",
      "constraint.staffing-coverage": "Keep the required qualified staff inside throughout the team\u2019s absence",
      "constraint.staffing-register": "Keep the unavailable staff count within the qualified roster",
      "constraint.event-access": "Record permission for this event, date and promotion window",
      "constraint.spending-permission": "Record spending authority covering the responsible manager, operating date and full cost",
      "constraint.dispatch-timing": "Complete the review before team departure and the promotion start",
      "constraint.contact-window": "Reach departing event guests before the contact window closes",
      "constraint.useful-arrival": "Allow enough travel time for interested guests to arrive within the useful window",
      "constraint.staff-return": "Keep staffing covered until the team returns after the contact window",
      "constraint.expense-limit": "Keep the plan\u2019s full additional expense within the spending limit"
    },
    "metadata": {
      "catalog": {
        "domain": {
          "id": "venue-operations",
          "label": "Venue operations"
        },
        "useCase": {
          "id": "deploy-street-team",
          "label": "Review a street-team deployment"
        }
      },
      "decisionPresentation": {
        "format": "decision-presentation/1",
        "title": "Promotion plans",
        "question": "Which promotion plans meet the recorded requirements?",
        "priorityLabel": "Shows which plans meet the recorded requirements. The manager records the choice separately.",
        "moneyFormat": {
          "currency": "USD",
          "divisor": 100
        },
        "columns": [
          {
            "id": "deployment",
            "source": "choice:deployment",
            "label": "Promotion plan",
            "valueLabels": {
              "hold": "Do not send a promotion team",
              "small-standard": "One-person promotion",
              "large-standard": "Two-person promotion",
              "large-discount": "Two-person discounted promotion"
            }
          },
          {
            "id": "status",
            "source": "status"
          },
          {
            "id": "inside",
            "source": {
              "kind": "derived",
              "id": "insideStaff"
            },
            "label": "Qualified staff remaining inside",
            "format": {
              "kind": "number"
            }
          },
          {
            "id": "expense",
            "source": "expense",
            "label": "Additional expense"
          },
          {
            "id": "blockers",
            "source": "blockers"
          }
        ]
      }
    }
  },
  "case": {
    "id": "street-team-friday",
    "parameters": {
      "venueId": "VENUE-SAM",
      "eventId": "EVENT-1120",
      "operatingDate": "2026-11-20",
      "actorId": "Sam",
      "qualifiedStaff": 7,
      "unavailableStaff": 0,
      "minimumInside": 4,
      "reviewMinute": 1170,
      "dispatchMinute": 1185,
      "promotionStartMinute": 1200,
      "eventExitMinute": 1215,
      "contactEndMinute": 1245,
      "staffReturnMinute": 1260,
      "customerJourneyMinutes": 30,
      "latestArrivalMinute": 1275,
      "expenseLimitMinor": 40000
    },
    "tables": {
      "options": [
        {
          "id": "hold",
          "label": "Do not send a promotion team",
          "promoters": 0,
          "expenseMinor": 0
        },
        {
          "id": "small-standard",
